refentry.refsect1:
&reftitle.description;
arrayarray_diff_key arrayarray arrayarrays
array from का keys लाई arrays from का keys सँग तुलना गर्दछ र फरक return गर्दछ। यो function array_diff जस्तै हो, तर यसमा values को सट्टा keys मा तुलना गरिन्छ।

  &reftitle.examples;



    array_diff_key को उदाहरण

key => value जोडीहरू from का दुई keys लाई (string) $key1 === (string) $key2  भएको अवस्थामा मात्र बराबर मानिन्छ। अर्को शब्दमा, एउटा strict type जाँच गरिन्छ, त्यसैले string representation एउटै हुनुपर्छ।


<?php
$array1 = array('blue' => 1, 'red' => 2, 'green' => 3, 'purple' => 4);
$array2 = array('green' => 5, 'yellow' => 7, 'cyan' => 8);

var_dump(array_diff_key($array1, $array2));
?>


    &example.outputs;


array(3) {
  ["blue"]=>
  int(1)
  ["red"]=>
  int(2)
  ["purple"]=>
  int(4)
}




<?php
$array1 = array('blue' => 1, 'red'  => 2, 'green' => 3, 'purple' => 4);
$array2 = array('green' => 5, 'yellow' => 7, 'cyan' => 8);
$array3 = array('blue' => 6, 'yellow' => 7, 'mauve' => 8);

var_dump(array_diff_key($array1, $array2, $array3));
?>


    &example.outputs;


array(2) {
  ["red"]=>
  int(2)
  ["purple"]=>
  int(4)
}
